SELECT

FROM project_briefing

    1 = 1

        AND project_id = #{param.projectId}


        AND briefing_name LIKE '%' || #{param.briefingTitle} || '%'


        AND briefing_type = #{param.briefingType}


        AND briefer_id IN (SELECT id FROM tbl_staff WHERE staff_name LIKE '%' || #{param.brieferName} || '%')


        AND briefing_status = #{param.briefingStatus}


        AND briefing_date >= #{param.briefingTimeStart}


        AND briefing_date <= #{param.briefingTimeEnd}


ORDER BY briefing_date DESC, create_time DESC

SELECT

FROM project_briefing

    1 = 1

        AND project_id = #{param.projectId}


        AND briefing_name LIKE '%' || #{param.briefingTitle} || '%'


        AND briefing_type = #{param.briefingType}


        AND briefer_id IN (SELECT id FROM tbl_staff WHERE staff_name LIKE '%' || #{param.brieferName} || '%')


        AND briefing_status = #{param.briefingStatus}


        AND briefing_date >= #{param.startDate}


        AND briefing_date <= #{param.endDate}


ORDER BY briefing_date DESC, create_time DESC

SELECT COUNT(*) as totalBriefings, SUM(CASE WHEN briefing_type = 1 THEN 1 ELSE 0 END) as qualityBriefings, SUM(CASE WHEN briefing_type = 2 THEN 1 ELSE 0 END) as safetyBriefings, SUM(CASE WHEN briefing_type = 3 THEN 1 ELSE 0 END) as technicalBriefings, SUM(CASE WHEN briefing_type = 4 THEN 1 ELSE 0 END) as paymentBriefings, SUM(CASE WHEN briefing_type = 5 THEN 1 ELSE 0 END) as progressBriefings, SUM(CASE WHEN briefing_type = 6 THEN 1 ELSE 0 END) as deliveryBriefings, SUM(CASE WHEN briefing_status = 1 THEN 1 ELSE 0 END) as plannedBriefings, SUM(CASE WHEN briefing_status = 2 THEN 1 ELSE 0 END) as completedBriefings, SUM(CASE WHEN briefing_status = 3 THEN 1 ELSE 0 END) as cancelledBriefings, SUM(CASE WHEN confirmation_status = 1 THEN 1 ELSE 0 END) as confirmedBriefings, SUM(CASE WHEN confirmation_status = 2 THEN 1 ELSE 0 END) as unconfirmedBriefings FROM project_briefing
1 = 1
AND project_id = #{projectId}

SELECT briefing_type, COUNT(*) as count, SUM(CASE WHEN briefing_status = 2 THEN 1 ELSE 0 END) as completedCount, SUM(CASE WHEN confirmation_status = 1 THEN 1 ELSE 0 END) as confirmedCount FROM project_briefing
1 = 1
AND project_id = #{projectId}
AND briefing_date >= #{startDate}
AND briefing_date <= #{endDate}
GROUP BY briefing_type ORDER BY count DESC

SELECT DATE_FORMAT(briefing_date, '%Y-%m') as month, COUNT(*) as totalCount, SUM(CASE WHEN briefing_status = 2 THEN 1 ELSE 0 END) as completedCount, SUM(CASE WHEN confirmation_status = 1 THEN 1 ELSE 0 END) as confirmedCount FROM project_briefing
1 = 1
AND project_id = #{projectId}
AND briefing_date >= #{startDate}
AND briefing_date <= #{endDate}
GROUP BY DATE_FORMAT(briefing_date, '%Y-%m') ORDER BY month DESC LIMIT 12

SELECT CASE WHEN COUNT(1) > 0 THEN 1 ELSE 0 END
FROM project_briefing
WHERE briefing_no = #{briefingNo}

    AND id != #{excludeId}
